function escapeHtml(value) {
  return String(value).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}

function canonical(path) {
  if (!path || path === "/") return CANONICAL_ORIGIN + "/";
  return CANONICAL_ORIGIN + path;
}

function metaRobots(indexable) {
  if (PREVIEW || !indexable) return "noindex, nofollow";
  return "index, follow";
}

function robotsTxt() {
  const sitemap = "Sitemap: " + CANONICAL_ORIGIN + "/sitemap.xml\n";
  if (PREVIEW) return "User-agent: *\nDisallow: /\n\n" + sitemap;
  return "User-agent: *\nAllow: /\nDisallow: /login\nDisallow: /received\n\n" + sitemap;
}

function sitemapXml() {
  return "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n  <url><loc>" + CANONICAL_ORIGIN + "/</loc></url>\n  <url><loc>" + CANONICAL_ORIGIN + "/join</loc></url>\n</urlset>\n";
}

function jsonLd() {
  const data = {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "Organization",
        "@id": CANONICAL_ORIGIN + "/#organization",
        "name": SITE,
        "url": CANONICAL_ORIGIN + "/",
        "logo": CANONICAL_ORIGIN + "/assets/walton-county-tourism-network-logo.webp",
        "description": DESCRIPTION,
        "areaServed": { "@type": "AdministrativeArea", "name": "Walton County, Florida" },
      },
      {
        "@type": "WebSite",
        "@id": CANONICAL_ORIGIN + "/#website",
        "name": SITE,
        "url": CANONICAL_ORIGIN + "/",
        "description": DESCRIPTION,
        "publisher": { "@id": CANONICAL_ORIGIN + "/#organization" },
      },
    ],
  };
  return JSON.stringify(data).replace(/</g, "\\u003c");
}

function nav(home) {
  const root = home ? "" : "/";
  return `
        <nav class="nav" aria-label="Main navigation">
          <button type="button" class="nav-toggle" aria-expanded="false" aria-controls="site-nav-menu">
            <span class="nav-toggle-bars" aria-hidden="true"><span></span><span></span><span></span></span>
            <span class="visually-hidden">Menu</span>
          </button>
          <div id="site-nav-menu" class="nav-menu">
            <a href="${root}#about">About</a>
            <a href="${root}#issues">Issues</a>
          </div>
          <a class="nav-login" href="${HUB_LOGIN_URL}">Login</a>
          <a class="button" href="/join">Join the mission</a>
        </nav>`;
}

const NAV_SCRIPT = `<script>
(function () {
  var nav = document.querySelector(".site-header .nav");
  var button = nav && nav.querySelector(".nav-toggle");
  var menu = document.getElementById("site-nav-menu");
  var label = button && button.querySelector(".visually-hidden");
  if (!nav || !button || !menu || !label) return;
  var desktop = window.matchMedia("(min-width: 880px)");
  function setOpen(open) {
    if (desktop.matches) open = false;
    button.setAttribute("aria-expanded", open ? "true" : "false");
    nav.classList.toggle("is-open", open);
    label.textContent = open ? "Close menu" : "Menu";
  }
  button.addEventListener("click", function () {
    setOpen(button.getAttribute("aria-expanded") !== "true");
  });
  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
      setOpen(false);
      button.focus();
    }
  });
  menu.addEventListener("click", function (event) {
    if (event.target.closest && event.target.closest("a")) setOpen(false);
  });
  document.addEventListener("click", function (event) {
    if (button.getAttribute("aria-expanded") === "true" && !nav.contains(event.target)) setOpen(false);
  });
  nav.addEventListener("focusout", function (event) {
    if (button.getAttribute("aria-expanded") === "true" && !nav.contains(event.relatedTarget)) setOpen(false);
  });
  function onDesktopChange() { setOpen(false); }
  if (desktop.addEventListener) desktop.addEventListener("change", onDesktopChange);
  else if (desktop.addListener) desktop.addListener(onDesktopChange);
})();
</script>`;

