function withHeaders(headers) {
  const out = { ...HEADERS, ...headers };
  if (PREVIEW) out["X-Robots-Tag"] = "noindex";
  return out;
}

function pageHeaders(type) {
  return withHeaders({ "Content-Type": type, "Cache-Control": "no-store" });
}

function html(body) {
  return new Response(body, { headers: pageHeaders("text/html; charset=utf-8") });
}

function text(status, body) {
  return new Response(body, { status, headers: pageHeaders("text/plain; charset=utf-8") });
}

function clean(value) {
  return String(value || "").replace(/[\r\n]+/g, " ").trim();
}

function isEmail(value) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

function field(form, name) {
  return clean(form.get(name));
}

function rawEmail(replyTo, subject, body) {
  return [
    "From: " + FROM_NAME + " <" + FROM + ">",
    "To: " + TO,
    "Reply-To: " + replyTo,
    "Subject: " + subject,
    "MIME-Version: 1.0",
    "Content-Type: text/plain; charset=utf-8",
    "Content-Transfer-Encoding: 8bit",
    "",
    body,
  ].join("\r\n");
}

async function sendMail(env, replyTo, subject, body) {
  const message = new EmailMessage(FROM, TO, rawEmail(replyTo, subject, body));
  await env.EMAIL.send(message);
}

function formFields(form) {
  const fields = {};
  for (const [key, value] of form.entries()) {
    fields[String(key)] = typeof value === "string" ? value : String(value);
  }
  return fields;
}

async function forwardJoinApplication(env, payload) {
  const key = env && env.HUB_INGEST_KEY;
  const hubUrl = env && env.HUB_URL;
  if (typeof key !== "string" || key === "") {
    console.error("Hub forward skipped: HUB_INGEST_KEY is not set.");
    return;
  }
  if (typeof hubUrl !== "string" || hubUrl === "") {
    console.error("Hub forward skipped: HUB_URL is not set.");
    return;
  }
  try {
    const response = await fetch(hubUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Hub-Key": key,
      },
      body: JSON.stringify(payload),
      signal: AbortSignal.timeout(4000),
    });
    await response.arrayBuffer();
    if (!response.ok) {
      console.error("Hub forward failed with status " + response.status + ".");
    }
  } catch (err) {
    const message = err && err.message ? err.message : "unknown error";
    console.error("Hub forward failed: " + message);
  }
}

function pngBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function isLoopback(hostname) {
  return hostname === "localhost" || hostname === "127.0.0.1" || hostname === "[::1]";
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    {
      let redirect = false;
      const target = new URL(url.toString());
      if (target.hostname === WWW_HOST) {
        target.hostname = new URL(CANONICAL_ORIGIN).hostname;
        redirect = true;
      }
      // Same http to https rule as the builders worker, except loopback,
      // so a local preview on http://127.0.0.1 can be opened.
      if (target.protocol === "http:" && !isLoopback(target.hostname)) {
        target.protocol = "https:";
        redirect = true;
      }
      if (target.pathname.length > 1 && target.pathname.endsWith("/")) {
        target.pathname = target.pathname.replace(/\/+$/, "") || "/";
        redirect = true;
      }
      if (redirect) return Response.redirect(target.toString(), 301);
    }
    const path = url.pathname === "/" ? "/index.html" : url.pathname;

    if (request.method === "POST" && url.pathname === "/login") {
      const form = await request.formData();
      const email = field(form, "email");
      const password = String(form.get("password") || "");
      if (!isEmail(email) || !password.trim()) {
        return text(400, "Please enter your email and password.");
      }
      return Response.redirect(new URL("/login?notice=1", request.url), 303);
    }

    if (request.method === "POST" && (url.pathname === "/contact" || url.pathname === "/join")) {
      const form = await request.formData();
      if (field(form, "company_fax")) {
        const next = url.pathname === "/join" ? "/received?for=join" : "/received?for=contact";
        return Response.redirect(new URL(next, request.url), 303);
      }

      try {
        if (url.pathname === "/contact") {
          const name = field(form, "name");
          const email = field(form, "email");
          const message = String(form.get("message") || "").trim();
          if (!name || !isEmail(email) || !message) {
            return text(400, "Please fill in your name, a valid email, and a message.");
          }
          await sendMail(
            env,
            email,
            "Tourism Network contact",
            "New contact message from the Walton County Tourism Network website.\n\nName: " + name + "\nEmail: " + email + "\n\nMessage:\n" + message
          );
          return Response.redirect(new URL("/received?for=contact", request.url), 303);
        }

        const name = field(form, "name");
        const email = field(form, "email");
        const phone = field(form, "phone");
        const company = field(form, "company");
        const role = field(form, "role");
        const industry = field(form, "industry");
        const years = field(form, "years_in_walton");
        const website = field(form, "website");
        const about = String(form.get("about") || "").trim();
        if (!name || !isEmail(email) || !phone || !company || !role || !industry || !years) {
          return text(400, "Please fill in all required fields with a valid email.");
        }
        await sendMail(
          env,
          email,
          "Tourism Network membership application",
          [
            "New membership application from the Walton County Tourism Network website.",
            "",
            "Full name: " + name,
            "Email: " + email,
            "Phone: " + phone,
            "Business or company: " + company,
            "Role: " + role,
            "Industry or type of tourism business: " + industry,
            "How long in Walton County: " + years,
            "Business website: " + (website || "(not provided)"),
            "",
            "About:",
            about || "(not provided)",
          ].join("\n")
        );
        const hubForward = forwardJoinApplication(env, {
          network: "tourism",
          name,
          email,
          submitted_at: new Date().toISOString(),
          source_url: url.origin + url.pathname,
          fields: formFields(form),
        });
        if (ctx && typeof ctx.waitUntil === "function") ctx.waitUntil(hubForward);
        return Response.redirect(new URL("/received?for=join", request.url), 303);
      } catch (err) {
        return html(failPage());
      }
    }

    if (request.method !== "GET" && request.method !== "HEAD") {
      return text(405, "Method not allowed");
    }

    const head = request.method === "HEAD";

    if (path === "/robots.txt") {
      return new Response(head ? null : robotsTxt(), {
        headers: withHeaders({ "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "public, max-age=3600" }),
      });
    }
    if (path === "/sitemap.xml") {
      return new Response(head ? null : sitemapXml(), {
        headers: withHeaders({ "Content-Type": "application/xml; charset=utf-8", "Cache-Control": "public, max-age=3600" }),
      });
    }
    if (path === "/favicon.png" || path === "/apple-touch-icon.png" || path === "/assets/walton-county-tourism-network-logo.webp" || path === "/assets/walton-county-tourism-network-og.jpg") {
      const b64 = path === "/favicon.png" ? FAVICON_PNG_B64 : path === "/apple-touch-icon.png" ? APPLE_TOUCH_PNG_B64 : path.endsWith(".jpg") ? OG_JPG_B64 : LOGO_WEBP_B64;
      const type = path.endsWith(".webp") ? "image/webp" : path.endsWith(".jpg") ? "image/jpeg" : "image/png";
      const bytes = pngBytes(b64);
      return new Response(head ? null : bytes, {
        headers: withHeaders({ "Content-Type": type, "Cache-Control": "public, max-age=86400" }),
      });
    }
    if (path === "/index.html") return html(head ? null : homePage());
    if (path === "/join" || path === "/join.html") return html(head ? null : joinPage());
    if (path === "/login" || path === "/login.html") {
      return Response.redirect(HUB_LOGIN_URL, 302);
    }
    if (path === "/received") {
      const page = url.searchParams.get("for") === "join" ? thanksPage("join") : thanksPage("contact");
      return html(head ? null : page);
    }

    const allowed = path === "/styles.css" || path.startsWith("/fonts/");
    if (!allowed || path.includes("..")) return text(404, "Not found");

    let upstream;
    try {
      upstream = await fetch(ORIGIN + path);
    } catch (err) {
      return text(404, "Not found");
    }
    if (!upstream.ok) return text(404, "Not found");
    const ext = path.slice(path.lastIndexOf("."));
    const type = TYPES[ext] || "application/octet-stream";
    return new Response(head ? null : upstream.body, {
      headers: withHeaders({ "Content-Type": type, "Cache-Control": "public, max-age=300" }),
    });
  },
};
